window.MUSEUM_CALENDAR={"dated":true,"01-01":{"t":"Первая в мире сеть кабельного телевидения (Москва, 30 абонентов)","d":"Кабельное телевидение начиналось не в Америке: в 1939-м в Москве картинку по проводам получали тридцать квартир.","href":"/muzei/izobreteniya/den/01-01/"},"01-02":{"t":"«Луна-1», первая межпланетная станция и 2-я космическая скорость","d":"Она промахнулась мимо Луны на шесть тысяч километров — и стала первым телом, навсегда вырвавшимся из притяжения Земли.","href":"/muzei/izobreteniya/den/01-02/"},"01-03":{"t":"Возрождение секрета булатной стали","d":"Потерянный на века секрет булата вернул русский инженер, первым в мире разглядев под микроскопом, из чего сделана сталь.","href":"/muzei/izobreteniya/den/01-03/"},"01-04":{"t":"Первое в мире радиоуправление (публичные демонстрации)","d":"Пильчиков взорвал заряд из другого конца зала, не прикоснувшись к нему, — за сто лет до дронов и умного дома.","href":"/muzei/izobreteniya/den/01-04/"},"01-05":{"t":"Первый в мире расчётный нефтепровод Балаханы–Черный город","d":"Перевозка нефти стоила дороже самой нефти — 24-летний инженер пустил её по трубе и оставил без работы десять тысяч возчиков.","href":"/muzei/izobreteniya/den/01-05/"},"01-06":{"t":"Орловская печать, И. И. Орлов, 1890–1891","d":"Радужный переход, который не берёт ни копир, ни принтер, придумал самоучка — и деньги мира печатают им до сих пор.","href":"/muzei/izobreteniya/den/01-06/"},"01-07":{"t":"Первое в мире коронарное шунтирование · [У] В. И. Колесов 1964","d":"Колесов пришил к живому, бьющемуся сердцу собственную артерию человека — за три года до того, как это сделал Запад","href":"/muzei/izobreteniya/den/01-07/"},"01-08":{"t":"«Ермак», первый в мире арктический ледокол","d":"Деньги на корабль, которого не было ни у одной державы, русскому адмиралу помог достать химик из школьной таблицы.","href":"/muzei/izobreteniya/den/01-08/"},"01-09":{"t":"Первый в мире гусеничный ход","d":"Крестьянин без образования придумал гусеницу, на которой держится вся тяжёлая техника планеты, — за 25 лет до американцев.","href":"/muzei/izobreteniya/den/01-09/"},"01-10":{"t":"Первый в мире ледокол «Пайлот»","d":"Купец срезал своему пароходу нос под углом — и судно перестало биться о лёд, а полезло на него сверху.","href":"/muzei/izobreteniya/den/01-10/"},"01-11":{"t":"Первый в мире бензиновый двигатель (для дирижабля)","d":"Костович собрал бензиновый мотор раньше, чем Даймлер и Бенц поставили такие на свои повозки.","href":"/muzei/izobreteniya/den/01-11/"},"01-12":{"t":"Первая в мире межконтинентальная баллистическая ракета Р-7","d":"Ракету делали как оружие, но она ни разу не выстрелила по цели — вместо этого вывела на орбиту спутник и Гагарина.","href":"/muzei/izobreteniya/den/01-12/"},"01-13":{"t":"К-278 «Комсомолец»: единственная в мире боевая ПЛ, погрузившаяся на 1027 м (рекорд не побит)","d":"Боевая подлодка ушла на километр под воду — глубже с тех пор не погружался никто, и рекорду уже сорок лет.","href":"/muzei/izobreteniya/den/01-13/"},"01-14":{"t":"Подлодки пр. 705 «Лира»: самые быстрые серийные ПЛ в истории (41+ узел, титан)","d":"Титановая лодка с реактором на жидком металле разгонялась так, что от неё не уходили торпеды НАТО.","href":"/muzei/izobreteniya/den/01-14/"},"01-15":{"t":"Первая в мире женщина-профессор математики","d":"Ковалевской пришлось выйти замуж фиктивно, чтобы попасть в университет, — а кафедру она получила первой женщиной в мире.","href":"/muzei/izobreteniya/den/01-15/"},"01-16":{"t":"Первая стыковка кораблей и переход через открытый космос («Союз-4/5»)","d":"Корабли состыковались, а перебраться из одного в другой можно было только снаружи — в скафандре, по обшивке, в пустоте.","href":"/muzei/izobreteniya/den/01-16/"},"01-17":{"t":"Аэродинамика как наука","d":"Жуковский вывел, откуда берётся подъёмная сила, — и авиация из авантюры стала наукой.","href":"/muzei/izobreteniya/den/01-17/"},"01-18":{"t":"Арифмометр Однера: самый массовый механический калькулятор в истории (стандарт мира ~100 лет, «Феликс»)","d":"Механический калькулятор из Петербурга считал на всех континентах почти сто лет — в СССР его звали «Феликс».","href":"/muzei/izobreteniya/den/01-18/"},"01-19":{"t":"Линейное программирование (Нобель по экономике)","d":"Канторович решал, как раскроить фанеру без отходов, а получил единственную в истории СССР Нобелевскую по экономике.","href":"/muzei/izobreteniya/den/01-19/"},"01-20":{"t":"Открытие витаминов, основы витаминологии (первым в мире)","d":"Мыши получали идеальную смесь белков, жиров и сахара — и умирали, пока Лунин не понял: в еде есть что-то ещё.","href":"/muzei/izobreteniya/den/01-20/"},"01-21":{"t":"Первая в мире АЭС (Обнинск)","d":"В Обнинске атом впервые дал не взрыв, а ток в розетку — и станция проработала почти полвека.","href":"/muzei/izobreteniya/den/01-21/"},"01-22":{"t":"Теория сверхтекучести (Нобель)","d":"Жидкий гелий сам ползёт вверх по стенке и убегает из сосуда — Ландау объяснил почему, а Нобеля получал в больнице.","href":"/muzei/izobreteniya/den/01-22/"},"01-23":{"t":"Учение о движении энергии, вектор Умова (первым в мире ввёл поток энергии)","d":"Умов первым описал энергию как поток — за десять лет до англичанина, чьим именем это назвали на Западе.","href":"/muzei/izobreteniya/den/01-23/"},"01-24":{"t":"Самая быстроходная в мире подлодка К-162 (титан)","d":"На испытаниях подлодка обогнала корабли сопровождения — её рекорд скорости под водой не побит до сих пор.","href":"/muzei/izobreteniya/den/01-24/"},"01-25":{"t":"Машины С. Н. Корсакова на перфокартах, 1832","d":"Академия наук ответила Корсакову, что он зря учит людей жить без собственного ума, — а его машина искала нужное среди сотен карточек","href":"/muzei/izobreteniya/den/01-25/"},"01-26":{"t":"Камера для подводной съёмки","d":"Водонепроницаемую камеру для морских съёмок собрал в 1886-м тот же петербуржец, что сделал и первый аэрофотоаппарат.","href":"/muzei/izobreteniya/den/01-26/"},"01-27":{"t":"Архитектура процессоров Pentium","d":"Человек, сделавший советский «Эльбрус», уехал в Intel — и заложил архитектуру процессора, который стоял почти в каждом компьютере мира.","href":"/muzei/izobreteniya/den/01-27/"},"01-28":{"t":"Вакцины Хавкина: первая в мире противохолерная (1892) и противочумная (1897)","d":"Хавкин ввёл холеру себе — выжил, и через пять лет его прививка останавливала чуму в Индии миллионами доз.","href":"/muzei/izobreteniya/den/01-28/"},"01-29":{"t":"Цельнометаллический дирижабль «Россия» (проект)","d":"Он предложил делать оболочку не из ткани, а из металла — на полвека раньше, чем такой дирижабль построили в Германии.","href":"/muzei/izobreteniya/den/01-29/"},"01-30":{"t":"Ранцевый парашют РК-1","d":"Парашют, который спасал лётчиков, в России отклонили: решили, что с ним пилоты станут бросать самолёты при первой поломке.","href":"/muzei/izobreteniya/den/01-30/"},"01-31":{"t":"Гиротрон, первый в мире источник мегаваттных миллиметровых волн · [У] А. В. Гапонов-Грехов 1964","d":"Гапонов-Грехов построил прибор, чьим лучом сегодня разогревают плазму в международном термоядерном реакторе","href":"/muzei/izobreteniya/den/01-31/"},"02-01":{"t":"Основы неврологии и психоневрологии","d":"Бехтерев описал столько участков мозга, что семь из них носят его имя, и спорил с Фрейдом на равных","href":"/muzei/izobreteniya/den/02-01/"},"02-02":{"t":"Гаубица «единорог»","d":"«Единорог» стрелял ядром и разрывной гранатой из одного ствола, а в Европе так научились только через сто лет","href":"/muzei/izobreteniya/den/02-02/"},"02-03":{"t":"Первая в мире мягкая посадка на Луну («Луна-9»)","d":"Никто на Земле не знал, выдержит ли лунная пыль аппарат, — «Луна-9» села и прислала первый снимок с поверхности","href":"/muzei/izobreteniya/den/02-03/"},"02-04":{"t":"Самовар","d":"Самовар — не про чай, а про инженерию: труба внутри воды греет её изнутри и кипятит вдвое быстрее плиты","href":"/muzei/izobreteniya/den/02-04/"},"02-05":{"t":"Гибкая (рулонная) фотоплёнка (раньше Kodak)","d":"Болдырев показал миру гибкую фотоплёнку в рулоне за десять лет до Kodak и патента на неё так и не взял","href":"/muzei/izobreteniya/den/02-05/"},"02-06":{"t":"Угольный противогаз","d":"Спасение от боевого газа нашлось в печке: прокалённый берёзовый уголь держал отраву лучше любой химии того времени","href":"/muzei/izobreteniya/den/02-06/"},"02-07":{"t":"Первая в мире троичная ЭВМ «Сетунь»","d":"Весь мир считает нулями и единицами, а машина Брусенцова считала тремя знаками и выходила экономичнее ровесниц","href":"/muzei/izobreteniya/den/02-07/"},"02-08":{"t":"Периодическая система элементов","d":"Менделеев оставил в таблице пустые клетки и описал вещества, которых никто не видел, — их нашли ровно такими","href":"/muzei/izobreteniya/den/02-08/"},"02-09":{"t":"Гелиобиология и аэроионификация («люстра Чижевского»)","d":"Чижевский связал вспышки на Солнце с эпидемиями и бунтами на Земле, сел за это, а его люстру потом вешали в больницах","href":"/muzei/izobreteniya/den/02-09/"},"02-10":{"t":"Аэросани (первые в мире)","d":"Там, где есть только снег, Россия сделала машину без колёс и гусениц: пропеллер гонит сани по насту быстрее автомобиля","href":"/muzei/izobreteniya/den/02-10/"},"02-11":{"t":"Первый в мире морской гидросамолёт (летающая лодка М-5)","d":"Григорович превратил корпус самолёта в лодку, и машина стала взлетать прямо с черноморской волны, без аэродрома","href":"/muzei/izobreteniya/den/02-11/"},"02-12":{"t":"Закон Ленца (электромагнитная индукция)","d":"Ленц первым записал формулой, что природа сопротивляется вмешательству, — на его правиле стоит каждый электродвигатель","href":"/muzei/izobreteniya/den/02-12/"},"02-13":{"t":"Гидросамолёты и амфибии «Бе»","d":"Таганрогская школа Бериева единственная в мире: Бе-200 садится на воду и набирает двенадцать тонн за двенадцать секунд","href":"/muzei/izobreteniya/den/02-13/"},"02-14":{"t":"Первый в мире монорельс","d":"Крепостной мастер Эльманов пустил вагонетки по одному брусу на столбах за полвека до английских патентов","href":"/muzei/izobreteniya/den/02-14/"},"02-15":{"t":"Первая в мире «мёртвая петля», рождение высшего пилотажа","d":"Инженеры считали, что вверх колёсами самолёт развалится, — Нестеров замкнул петлю и сел под арест за риск казённым имуществом","href":"/muzei/izobreteniya/den/02-15/"},"02-16":{"t":"Первый в мире радиозонд","d":"Шар Молчанова поднялся на десять километров и сам рассказал по радио, что творится наверху, — так начался прогноз погоды","href":"/muzei/izobreteniya/den/02-16/"},"02-17":{"t":"Первый в мире электрический трамвай","d":"Пироцкий пустил вагон на электричестве по петербургским рельсам, денег не нашёл — и через год трамвай стал немецким","href":"/muzei/izobreteniya/den/02-17/"},"02-18":{"t":"Почвоведение как наука, первое в мире","d":"Докучаев доказал, что чернозём — живое тело со своей историей, и русский эталон почвы увезли в Париж","href":"/muzei/izobreteniya/den/02-18/"},"02-19":{"t":"Цветная фотография России · С. М. Прокудин-Горский, р. 1863","d":"Прокудин-Горский снимал одно и то же через три фильтра подряд, поэтому Россию 1910 года мы видим в настоящем цвете","href":"/muzei/izobreteniya/den/02-19/"},"02-20":{"t":"Первая в мире модульная орбитальная станция «Мир»","d":"Станцию «Мир» собирали на орбите по модулю, и пятнадцать лет полёта доказали: человек может жить в космосе годами","href":"/muzei/izobreteniya/den/02-20/"},"02-21":{"t":"Медицинская микробиология, первая в России станция прививок от бешенства","d":"Гамалея привёз от Пастера прививку от бешенства и открыл в Одессе станцию, куда везли укушенных со всей империи","href":"/muzei/izobreteniya/den/02-21/"},"02-22":{"t":"Первый в мире промышленный индукционный нагрев токами высокой частоты","d":"Вологдин научился калить металл без огня: ток высокой частоты греет деталь изнутри, так закаляют коленвалы до сих пор","href":"/muzei/izobreteniya/den/02-22/"},"02-23":{"t":"Первые в мире реактивные снаряды залпового огня «Катюша» (полигонные испытания)","d":"Идея была простая и страшная — не один точный выстрел, а залп по квадрату, и на полигоне это проверили за два года до войны","href":"/muzei/izobreteniya/den/02-23/"},"02-24":{"t":"Первая в мире мощная радиовещательная станция (Коминтерн, 1922)","d":"Двенадцати киловатт в эфире не было ни у кого в мире: Москву слушала Европа, а лампы для станции точили руками","href":"/muzei/izobreteniya/den/02-24/"},"02-25":{"t":"Первый в мире токамак Т-1 · Л. А. Арцимович, 1958","d":"Слово «токамак» во всех языках мира русское: магнитную бутылку для звезды построили в Москве","href":"/muzei/izobreteniya/den/02-25/"},"02-26":{"t":"Первый в мире промышленный синтез синтетического каучука","d":"Своих колоний у страны не было, и Лебедев сделал каучук из спирта — первый в мире завод синтетической резины пошёл у нас","href":"/muzei/izobreteniya/den/02-26/"},"02-27":{"t":"Пересадка роговицы и тканевая терапия","d":"Филатов вернул зрение тысячам слепых роговицей умерших: охлаждённая ткань приживалась лучше свежей","href":"/muzei/izobreteniya/den/02-27/"},"02-28":{"t":"Первая в мире теория расчёта мостовых ферм · Д. И. Журавский, 1844–1855","d":"До Журавского мосты рушились под поездами, пока он не сосчитал, какой брус тянет, а какой давит","href":"/muzei/izobreteniya/den/02-28/"},"03-01":{"t":"Первая русская печатная книга «Апостол»","d":"Фёдоров сам резал шрифт и варил краску, набор вышел чище европейского — а печатников после этого выгнали из Москвы","href":"/muzei/izobreteniya/den/03-01/"},"03-02":{"t":"Спонтанное деление ядер урана (открытие)","d":"Флёров увидел, что уран разваливается сам, а потом по внезапному молчанию западных журналов понял: там делают бомбу","href":"/muzei/izobreteniya/den/03-02/"},"03-03":{"t":"Органическая химия, реакции Фаворского","d":"Именную реакцию в химии получают единицы, а Фаворский дал миру целое семейство — на нём стоит синтетический каучук","href":"/muzei/izobreteniya/den/03-03/"},"03-04":{"t":"Принцип автофазировки, синхрофазотрон","d":"Ускорители упёрлись в потолок, пока Векслер не научил разбегающиеся частицы держать строй самих себя","href":"/muzei/izobreteniya/den/03-04/"},"03-05":{"t":"Автоматическая дуговая сварка под флюсом","d":"Патон научил машину варить броню под слоем флюса быстрее и прочнее человека, и Т-34 пошли с конвейера потоком","href":"/muzei/izobreteniya/den/03-05/"},"03-06":{"t":"Первый в мире обезболивающий наркоз на поле боя (эфирный)","d":"Пирогов привёз эфир на войну, и раненого впервые перестали держать вчетвером, пока хирург режет","href":"/muzei/izobreteniya/den/03-06/"},"03-07":{"t":"Первый в мире токарный станок с механическим суппортом","d":"Пока резец держали руками, точность кончалась там, где уставала рука, — Нартов зажал его в суппорт","href":"/muzei/izobreteniya/den/03-07/"},"03-08":{"t":"Давление света (экспериментально доказано впервые)","d":"Лебедев поймал в опыте давление света — силу в миллиард раз слабее веса пылинки, в которую до него только верили","href":"/muzei/izobreteniya/den/03-08/"},"03-09":{"t":"Турбобур (турбинное бурение скважин)","d":"Капелюшников опустил двигатель на самое дно скважины, и колонна труб перестала греть землю трением по всей длине","href":"/muzei/izobreteniya/den/03-09/"},"03-10":{"t":"Подводный минный заградитель «Краб» · М. П. Налётов, 1912","d":"Мичман Налётов строил «Краб» в осаждённом Порт-Артуре: лодку, которая подкрадывается под водой и сеет мины у чужого порога","href":"/muzei/izobreteniya/den/03-10/"},"03-11":{"t":"Открытие мембранного (пристеночного) пищеварения, мировой приоритет","d":"Двести лет учили, что пища переваривается в полости кишки, — Уголев нашёл главное на её ворсинках и переписал учебники","href":"/muzei/izobreteniya/den/03-11/"},"03-12":{"t":"Учение о биосфере и ноосфере","d":"Вернадский посчитал живое вещество как силу геологического масштаба: не Земля носит жизнь, а жизнь переделала Землю","href":"/muzei/izobreteniya/den/03-12/"},"03-13":{"t":"Теория функциональных систем (физиология поведения)","d":"Анохин показал, что организм собирает органы в команду под задачу и распускает её, когда задача решена","href":"/muzei/izobreteniya/den/03-13/"},"03-14":{"t":"Паровая машина непрерывного действия · И. И. Ползунов, 1763","d":"За двадцать лет до Уатта Ползунов собрал на Алтае паровую машину без водяного колеса и умер за неделю до пуска","href":"/muzei/izobreteniya/den/03-14/"},"03-15":{"t":"Первые в мире полупроводниковые гетероструктуры — основа лазерных диодов, солнечных батарей, смартфонов (Нобель)","d":"Нобелевскую премию Алфёрову дали за слой толщиной в несколько атомов, без которого нет ни оптоволокна, ни лазера в плеере","href":"/muzei/izobreteniya/den/03-15/"},"03-16":{"t":"Радио","d":"Попов поймал прибором грозу за версту, а через год передал в эфир первую в мире радиограмму из двух слов","href":"/muzei/izobreteniya/den/03-16/"},"03-17":{"t":"Стартовые (пусковые) ракетные комплексы","d":"Ракету видят все, стартовый стол — никто, а Бармин построил то, что держит, заправляет и отпускает её за секунды","href":"/muzei/izobreteniya/den/03-17/"},"03-18":{"t":"Первый выход человека в открытый космос (Леонов, «Восход-2»)","d":"В вакууме скафандр раздулся, и Леонов стравил давление вопреки инструкции, чтобы влезть обратно в шлюз","href":"/muzei/izobreteniya/den/03-18/"},"03-19":{"t":"Ледокольные пароходы «Таймыр» и «Вайгач» · Адмиралтейские верфи, 1909","d":"Корпус скроили так, чтобы лёд не раздавил судно, а выжал его наверх, — за полвека до атомных ледоколов","href":"/muzei/izobreteniya/den/03-19/"},"03-20":{"t":"Первый в мире магистральный тепловоз","d":"Паровозу вода и уголь нужны каждые сто вёрст, а тепловоз Гаккеля прошёл пустыню без единой заправки водой","href":"/muzei/izobreteniya/den/03-20/"},"03-21":{"t":"Самолёт Можайского, один из первых в мире","d":"За двадцать лет до братьев Райт морской офицер поднял с земли аппарат с крылом, винтами и паровой машиной","href":"/muzei/izobreteniya/den/03-21/"},"03-22":{"t":"Первая в мире сварка под водой","d":"Хренов заставил сварочную дугу гореть под водой в собственном газовом пузыре, и корабли стали чинить на плаву","href":"/muzei/izobreteniya/den/03-22/"},"03-23":{"t":"Первый отечественный турбореактивный двигатель","d":"Люлька подал проект реактивного двигателя, когда все летали на винтах, и, уходя на фронт, замуровал чертежи в стену","href":"/muzei/izobreteniya/den/03-23/"},"03-24":{"t":"Люминесценция и лампы дневного света · С. И. Вавилов, р. 1891","d":"Вавилов объяснил, почему вещество светится без нагрева, и превратил это объяснение в лампу дневного света","href":"/muzei/izobreteniya/den/03-24/"},"03-25":{"t":"Нефтеперегонный завод непрерывного действия · братья Дубинины, 1823","d":"Трое крепостных братьев поставили на Тереке перегонный куб непрерывного действия, когда нефтью ещё лечили овец","href":"/muzei/izobreteniya/den/03-25/"},"03-26":{"t":"Первые в мире опыты по радиолокации (РЛС)","d":"Ощепков предложил видеть самолёт по отражённой волне за шесть лет до Битвы за Британию, а потом сел по доносу","href":"/muzei/izobreteniya/den/03-26/"},"03-27":{"t":"«Луна-10» — первый искусственный спутник Луны, 1966","d":"Первый спутник Луны должен был сыграть «Интернационал» прямо на съезд партии, и накануне мелодия начала сбиваться","href":"/muzei/izobreteniya/den/03-27/"},"03-28":{"t":"Первые в мире опыты по передаче электроэнергии на расстояние","d":"Якоби пустил по Неве против течения первое в мире судно, которое двигал электрический ток, а не пар","href":"/muzei/izobreteniya/den/03-28/"},"03-29":{"t":"Механика мёрзлых грунтов и пенетрометр · Н. А. Цытович, 1934","d":"Полстраны стоит на мерзлоте, которая при нагреве превращается в кашу, — Цытович научился мерить её прочность прибором","href":"/muzei/izobreteniya/den/03-29/"},"03-30":{"t":"Штурмовик Ил-2 и самолёты Ильюшина","d":"Ильюшин сделал броню не навеской, а самим корпусом, и Ил-2 выпустили тридцать шесть тысяч — больше любого самолёта в истории","href":"/muzei/izobreteniya/den/03-30/"},"03-31":{"t":"Дешифровка письменности майя","d":"Письменность майя прочитал человек, ни разу не бывавший в Мексике, — по фотокопиям, из ленинградского кабинета","href":"/muzei/izobreteniya/den/03-31/"},"04-01":{"t":"Самолёты «Як»","d":"Яковлев начинал с планёра в бывшей конюшне, а кончил тем, что каждый третий истребитель войны носил его буквы","href":"/muzei/izobreteniya/den/04-01/"},"04-02":{"t":"Мобильный радиотелефон ЛК-1 · Л. И. Куприянович, 1957","d":"Трубка Куприяновича с диском набора звонила на любой городской номер в 1957-м, когда Motorola о таком только думала","href":"/muzei/izobreteniya/den/04-02/"},"04-03":{"t":"Первый в мире нефтеналивной танкер «Зороастр» · 1878","d":"Нобели сделали трюм судна одним огромным баком, и нефть перестала ездить в бочках, половина веса которых — тара","href":"/muzei/izobreteniya/den/04-03/"},"04-04":{"t":"Первая в мире пересадка почки (опыты)","d":"Вороной пересадил женщине почку умершего человека за двадцать лет до того, как мир признал это возможным","href":"/muzei/izobreteniya/den/04-04/"},"04-05":{"t":"Аэродинамика, теорема Чаплыгина","d":"Почему крыло держит самолёт, не мог посчитать никто, пока Чаплыгин с Жуковским не вывели формулу подъёмной силы","href":"/muzei/izobreteniya/den/04-05/"},"04-06":{"t":"Антисептическая и полостная хирургия","d":"До Склифосовского вскрытая брюшная полость почти всегда означала смерть от заражения — он заставил операционную быть чистой","href":"/muzei/izobreteniya/den/04-06/"},"04-07":{"t":"Первая в мире подводная лодка «Дельфин» с двигателем внутреннего сгорания","d":"Лодки до «Дельфина» либо ползали на аккумуляторах, либо дымили паром, а он взял мотор для верха и электричество для глубины","href":"/muzei/izobreteniya/den/04-07/"},"04-08":{"t":"Гусеничный вездеход/танк «Вездеход»","d":"Двадцатидвухлетний Пороховщиков поставил машину на широкую ленту и прошёл там, где вязли лошади, — за год до британских танков","href":"/muzei/izobreteniya/den/04-08/"},"04-09":{"t":"Первый в мире дизельный теплоход «Вандал»","d":"На Волге построили судно, где вместо котла размером с дом стоял дизель, — так мир узнал слово «теплоход»","href":"/muzei/izobreteniya/den/04-09/"},"04-10":{"t":"Первый в мире оптический прицел для артиллерии","d":"Нартов приделал к пушке зрительную трубу с сеткой, когда пушкари ещё целились на глаз и по памяти","href":"/muzei/izobreteniya/den/04-10/"},"04-11":{"t":"Первая в мире сварка в космосе — установка «Вулкан» · 1969","d":"В вакууме шов может вскипеть или не схватиться вовсе, и Институт Патона сделал автомат, который варит прямо на орбите","href":"/muzei/izobreteniya/den/04-11/"},"04-12":{"t":"Первый полёт человека в космос (Ю. Гагарин, «Восток-1»)","d":"Никто не знал, останется ли человек в невесомости в своём уме, поэтому управление кораблём заперли на код в конверте","href":"/muzei/izobreteniya/den/04-12/"},"04-13":{"t":"Первая в мире глубоководная морская мина","d":"Английский флот вошёл в Финский залив и не подошёл к Кронштадту: под водой его ждали мины Якоби с электрическим запалом","href":"/muzei/izobreteniya/den/04-13/"},"04-14":{"t":"Трёхлинейная винтовка Мосина","d":"Винтовку Мосина солдат нёс и в Первую мировую, и в Великую Отечественную, и на парад Победы — шестьдесят лет службы","href":"/muzei/izobreteniya/den/04-14/"},"04-15":{"t":"Теория цепных химических реакций (Нобель)","d":"Семёнов объяснил, что взрыв — не много огня сразу, а лавина: одна частица рождает две, две рождают четыре","href":"/muzei/izobreteniya/den/04-15/"},"04-16":{"t":"«Нефтяные Камни» — первый в мире морской нефтяной город · 1949","d":"В сорока километрах от берега на стальных эстакадах вырос настоящий город: улицы, дома, хлебозавод — посреди Каспия","href":"/muzei/izobreteniya/den/04-16/"},"04-17":{"t":"Ракетный электробаллистический прибор · К. И. Константинов, 1844","d":"Ракеты летали, но скорость их не мерил никто, — Константинов построил прибор и превратил стрельбу наугад в расчёт","href":"/muzei/izobreteniya/den/04-17/"},"04-18":{"t":"Первые в мире алмазы на Урале: открытие месторождения","d":"Четырнадцатилетний крепостной промывал золото и вынес мастеру камешек, которым режут стекло, — первый алмаз России","href":"/muzei/izobreteniya/den/04-18/"},"04-19":{"t":"Первая в мире орбитальная станция «Салют-1»","d":"До «Салюта» в космосе жили в кабине размером со шкаф, а станция впервые дала человеку на орбите настоящий дом","href":"/muzei/izobreteniya/den/04-19/"},"04-20":{"t":"Первый в мире рейс атомного ледокола «Ленин» по Северному морскому пути","d":"Обычному ледоколу угля хватало на месяц и полтрюма занимало топливо, а атомному хватило реактора на весь сезон","href":"/muzei/izobreteniya/den/04-20/"},"04-21":{"t":"Первый в России самодвижущийся экипаж («самокатка») с трёхколёсным шасси и коробкой передач","d":"Коляска Кулибина ехала без лошади: слуга качал педали, а внутри работали маховик, тормоз и переключение скоростей","href":"/muzei/izobreteniya/den/04-21/"},"04-22":{"t":"Электродуговая сварка · Н. Н. Бенардос, 1882","d":"Бенардос стал соединять металл не заклёпками, а молнией: дуга от угольного электрода сплавляла два куска в один","href":"/muzei/izobreteniya/den/04-22/"},"04-23":{"t":"Первая в мире система спутникового телевещания","d":"Чтобы поймать сигнал из космоса, глухому посёлку хватало антенны и приставки — телевидение пришло туда, где нет вышек","href":"/muzei/izobreteniya/den/04-23/"},"04-24":{"t":"Подземная газификация угля · первая в мире промышленная станция, 1933","d":"Менделеев предложил поджечь угольный пласт под землёй и брать наверх готовый газ — через полвека так и сделали","href":"/muzei/izobreteniya/den/04-24/"},"04-25":{"t":"Теория вероятностей (аксиоматика)","d":"Случайность считали делом азартных игр, пока Колмогоров не подвёл под неё шесть строк аксиом","href":"/muzei/izobreteniya/den/04-25/"},"04-26":{"t":"Противочумные меры и обеззараживание · Д. С. Самойлович, 1771","d":"В московскую чуму Самойлович доказал, что зараза передаётся прикосновением, а не дурным воздухом","href":"/muzei/izobreteniya/den/04-26/"},"04-27":{"t":"Гнойная хирургия · В. Ф. Войно-Ясенецкий (архиепископ Лука), р. 1877","d":"Он оперировал в тюремной робе и в архиерейском облачении, а Сталинскую премию получил, оставаясь ссыльным","href":"/muzei/izobreteniya/den/04-27/"},"04-28":{"t":"Первый в мире электромагнитный телеграф · П. Л. Шиллинг, 1832","d":"В петербургской квартире Шиллинг протянул провода из кабинета в кабинет, и стрелки сложили первое слово по электричеству","href":"/muzei/izobreteniya/den/04-28/"},"04-29":{"t":"Пистолет-пулемёт ППШ","d":"ППШ штамповали на обычном прессе в любом городе за считанные часы — шесть миллионов автоматов за войну","href":"/muzei/izobreteniya/den/04-29/"},"04-30":{"t":"Первый в мире аппарат искусственного кровообращения (автожектор) — прообраз АИК в современной хирургии","d":"Аппарат Брюхоненко держал жизнь в отделённой от тела голове собаки: она моргала, щурилась и глотала","href":"/muzei/izobreteniya/den/04-30/"},"05-01":{"t":"Первый в мире одноместный вертолёт с автоматом перекоса в испытаниях","d":"Студент Юрьев решил задачу, о которую разбился Леонардо: лопасти научились менять угол по кругу и не рвать машину","href":"/muzei/izobreteniya/den/05-01/"},"05-02":{"t":"ГОЭЛРО — план электрификации России, 1920","d":"В стране без хлеба и гвоздей чертили карту из тридцати электростанций на пятнадцать лет вперёд, и Уэллс назвал это фантазией","href":"/muzei/izobreteniya/den/05-02/"},"05-03":{"t":"Первый в мире турбовинтовой межконтинентальный лайнер Ту-114","d":"Ту-114 шёл 871 километр в час — самый быстрый винтовой самолёт в истории, и внутри у него были спальня и ресторан","href":"/muzei/izobreteniya/den/05-03/"},"05-04":{"t":"Комбинационное рассеяние света","d":"Мандельштам поймал, как свет чуть меняет цвет внутри вещества, и по этому «чуть» теперь узнают состав чего угодно","href":"/muzei/izobreteniya/den/05-04/"},"05-05":{"t":"Электродуговая сварка металлическим электродом","d":"До Славянова дуга лишь плавила края, а шов набивали чем придётся, — он сделал электрод из того же металла, что деталь","href":"/muzei/izobreteniya/den/05-05/"},"05-06":{"t":"Первый в мире научный полёт на аэростате · Я. Д. Захаров, 1804","d":"До Захарова на шарах летали ради публики, а он поднялся с термометрами и списком опытов — первым в мире ради науки","href":"/muzei/izobreteniya/den/05-06/"},"05-07":{"t":"Первая демонстрация радиоприёмника (День радио)","d":"Прибор Попова ловил разряды молний за вёрсты, и через год им передали первую в мире радиограмму","href":"/muzei/izobreteniya/den/05-07/"},"05-08":{"t":"Подводная лодка К-162 «Анчар», 1969","d":"Титановая К-162 давала сорок пять узлов под водой, догоняла авианосец на полном ходу, и рекорд её не побит до сих пор","href":"/muzei/izobreteniya/den/05-08/"},"05-09":{"t":"Первая в мире передача изображения на ЭЛТ (электронное ТВ)","d":"На экране Розинга светились всего четыре белые полоски, но это было первое в мире электронное изображение","href":"/muzei/izobreteniya/den/05-09/"},"05-10":{"t":"Светодиод («свечение Лосева»), первое полупроводниковое свечение","d":"Радиолюбитель из Нижнего заметил, что карборунд светится под током, и предложил делать из него лампы без нити накала","href":"/muzei/izobreteniya/den/05-10/"},"05-11":{"t":"Первый в мире двигатель на водороде в блокадном Ленинграде","d":"В блокаду бензина не было вовсе, и Шелищ пустил отработанный водород аэростатов в мотор лебёдки — впервые в мире","href":"/muzei/izobreteniya/den/05-11/"},"05-12":{"t":"Телефонная трубка (микрофон+телефон вместе) и АТС","d":"Голубицкий соединил микрофон и телефон в одной трубке, и телефон стал вещью, которую держат у уха","href":"/muzei/izobreteniya/den/05-12/"},"05-13":{"t":"Древнейшее в мире колесо со спицами и боевая колесница (Синташта, Аркаим, Южный Урал)","d":"Под Челябинском нашли колесницы старше египетских: колесо у них уже не сплошной диск, а обод на спицах","href":"/muzei/izobreteniya/den/05-13/"},"05-14":{"t":"Хроматография · М. С. Цвет, р. 14 мая 1872","d":"Ботаник пропустил вытяжку зелёного листа через трубку с мелом, и смесь сама разошлась цветными кольцами","href":"/muzei/izobreteniya/den/05-14/"},"05-15":{"t":"Учение об иммунитете, фагоцитоз (Нобель)","d":"Мечников воткнул шип розы в личинку морской звезды и увидел, как клетки сползаются к занозе и пожирают её","href":"/muzei/izobreteniya/den/05-15/"},"05-16":{"t":"Математика, теория механизмов и приближений","d":"Чебышёв строил шагающие механизмы за век до роботов, а его математика до сих пор считает всё от радаров до статистики","href":"/muzei/izobreteniya/den/05-16/"},"05-17":{"t":"Перехват баллистической ракеты · система «А», Г. В. Кисунько, 1961","d":"Попасть ракетой в ракету считали всё равно что пулей в пулю, — Кисунько попал, и цель рассыпалась над полигоном","href":"/muzei/izobreteniya/den/05-17/"},"05-18":{"t":"Прототип персонального компьютера и первый плоттер","d":"Инженер из Омска подал заявку на прибор с экраном, клавиатурой и памятью за годы до первого персонального компьютера","href":"/muzei/izobreteniya/den/05-18/"},"05-19":{"t":"Первый в мире вертикальный взлёт самолёта-штурмовика (Як-36)","d":"Як-36 зависал над полосой без разбега почти одновременно с британцами, и таких машин в мире строили только две страны","href":"/muzei/izobreteniya/den/05-19/"},"05-20":{"t":"Первый в мире коммерческий видеомагнитофон","d":"Русский эмигрант назвал калифорнийскую фирму своими инициалами, и его Ampex первым в мире записал телевидение на ленту","href":"/muzei/izobreteniya/den/05-20/"},"05-21":{"t":"Дрейфующая станция «СП-1» · И. Д. Папанин, 21 мая 1937","d":"Четверо высадились на льдину у полюса и девять месяцев плыли через океан, ведя научный журнал, пока лёд не раскололся","href":"/muzei/izobreteniya/den/05-21/"},"05-22":{"t":"Останкинская телебашня · Н. В. Никитин, 1967","d":"Пятьсот сорок метров бетона держат не сваи, а полторы сотни натянутых канатов и фундамент глубиной меньше пяти метров","href":"/muzei/izobreteniya/den/05-22/"},"05-23":{"t":"Плазменный двигатель СПД на «Метеоре-18», 1971","d":"Тяга у него как от листа бумаги на ладони, зато месяцами без остановки — наш двигатель первым отработал такое на орбите","href":"/muzei/izobreteniya/den/05-23/"},"05-24":{"t":"Первая в мире регулярная почтовая служба на дирижаблях","d":"«Граф Цеппелин» и «Малыгин» встретились у Земли Франца-Иосифа и обменялись мешками писем прямо во льдах","href":"/muzei/izobreteniya/den/05-24/"},"05-25":{"t":"«Русский витязь» · И. И. Сикорский, р. 1889","d":"Инженеры мира считали, что больше двух моторов самолёт не поднимет, — Сикорский поставил четыре и поднял","href":"/muzei/izobreteniya/den/05-25/"},"05-26":{"t":"Плавучая АЭС «Академик Ломоносов» · Певек, 2020","d":"Атомную станцию собрали на верфи и потащили буксирами через Ледовитый океан — теперь она греет и освещает Певек","href":"/muzei/izobreteniya/den/05-26/"},"05-27":{"t":"Первый в мире безэкипажный танк (телетанк Т-26)","d":"Танк без человека внутри шёл в атаку по радиокоманде, стрелял и ставил дымы — таких у нас были десятки ещё до войны","href":"/muzei/izobreteniya/den/05-27/"},"05-28":{"t":"Первая в мире ночная бомбардировка авиацией (Галиция)","d":"Летать ночью считали самоубийством без горизонта и огней, — экипажи «Ильи Муромца» ушли в темноту первыми в мире","href":"/muzei/izobreteniya/den/05-28/"},"05-29":{"t":"Реактор на быстрых нейтронах БН-600, 1980","d":"БН-600 сжигает то, что для обычной станции радиоактивный отход, и вместо воды по нему течёт жидкий натрий","href":"/muzei/izobreteniya/den/05-29/"},"05-30":{"t":"Полёт самолёта с ядерным реактором на борту · Ту-95ЛАЛ, 1961","d":"В брюхе бомбардировщика возили работающий атомный реактор и смотрели, выдержит ли экипаж за свинцовой стеной","href":"/muzei/izobreteniya/den/05-30/"},"05-31":{"t":"Первый в мире прыжок с парашютом из стратосферы (рекорд СССР)","d":"Прыгать оттуда, где кипит кровь и нечем дышать, до них не пробовал никто: гондола, минус пятьдесят, кислородный прибор","href":"/muzei/izobreteniya/den/05-31/"},"06-01":{"t":"Кольская сверхглубокая скважина · [У] 1970–1990","d":"Двадцать лет бурили одну дыру в земле и прошли двенадцать километров: там, где ждали гранит, оказалось другое","href":"/muzei/izobreteniya/den/06-01/"},"06-02":{"t":"Первый в мире ракетный двигатель на гиперголическом топливе","d":"Глушко нашёл топливо, которое загорается само, едва два компонента встретились, — без свечи и без поджига","href":"/muzei/izobreteniya/den/06-02/"},"06-03":{"t":"Раскрытие механизма фотосинтеза","d":"Тимирязев доказал, что лист зелен не для красоты: он ловит красные лучи и кладёт солнечную энергию в запас","href":"/muzei/izobreteniya/den/06-03/"},"06-04":{"t":"Основоположник нейрохирургии","d":"До Бурденко в мозг лезли на свой страх и риск, а он сделал операции на мозге ремеслом с правилами и институтом","href":"/muzei/izobreteniya/den/06-04/"},"06-05":{"t":"Аппарат для механического сшивания кровеносных сосудов","d":"Сосуд толщиной со спичку руками шьют полчаса, а машинка Гудова сшивала его скобками за несколько секунд","href":"/muzei/izobreteniya/den/06-05/"},"06-06":{"t":"«Тетрис» · [И] А. Пажитнов, 1984","d":"Научный сотрудник написал «Тетрис» на служебной машине, чтобы проверить, как человек справляется с потоком фигур","href":"/muzei/izobreteniya/den/06-06/"},"06-07":{"t":"«Луна-16»: доставка лунного грунта автоматом · [У] 1970","d":"Американцы привезли лунный камень руками космонавтов, а наш аппарат сел, пробурил, взял сто грамм и улетел сам","href":"/muzei/izobreteniya/den/06-07/"},"06-08":{"t":"«Прогресс»: автоматический грузовик орбиты · [У] 1978","d":"Станция живёт, пока ей везут воду, еду и топливо, — «Прогресс» первым стал находить её и стыковаться без экипажа","href":"/muzei/izobreteniya/den/06-08/"},"06-09":{"t":"«Каисса»: первый чемпион мира среди программ · [У] 1974","d":"В Стокгольме собрали шахматные программы со всего мира, и первой чемпионкой планеты стала советская «Каисса»","href":"/muzei/izobreteniya/den/06-09/"},"06-10":{"t":"Первый в мире противоминный трал на военных кораблях","d":"Мину на якоре с борта не видно, и корабль узнаёт о ней взрывом, — русские моряки потащили за собой трос между катерами","href":"/muzei/izobreteniya/den/06-10/"},"06-11":{"t":"Синтезатор АНС · [У] Е. А. Мурзин, 1958","d":"Синтезатор без единой клавиши: звук на нём рисуют иглой по чёрному стеклу, и так написана музыка к «Солярису»","href":"/muzei/izobreteniya/den/06-11/"},"06-12":{"t":"«Спутник-2»: Лайка на орбите · [У] 1957","d":"Через месяц после первого спутника на орбиту ушла дворняга из московского двора и доказала, что живое там выживает","href":"/muzei/izobreteniya/den/06-12/"},"06-13":{"t":"Учение о доминанте, основы физиологии поведения (первое в мире)","d":"Ухтомский объяснил, почему голодный видит еду повсюду, а влюблённый — одно лицо: в мозге всегда горит один очаг","href":"/muzei/izobreteniya/den/06-13/"},"06-14":{"t":"Ка-50 «Чёрная акула» и соосная школа Камова · [У] первый полёт 1982","d":"Из вертолёта не катапультируешься — над головой винт, и камовцы сделали так, чтобы лопасти отстреливались за миг","href":"/muzei/izobreteniya/den/06-14/"},"06-15":{"t":"Аппарат Илизарова, чрескостный остеосинтез","d":"Сельский врач из Кургана сращивал кости спицами и кольцами и обнаружил, что под растяжением кость растёт сама","href":"/muzei/izobreteniya/den/06-15/"},"06-16":{"t":"Первая женщина в космосе (В. Терешкова)","d":"Двадцатишестилетняя ткачиха с парашютным разрядом провела на орбите трое суток — больше всех американцев вместе взятых","href":"/muzei/izobreteniya/den/06-16/"},"06-17":{"t":"Первый в мире серийный реактивный пассажирский самолёт Ту-104","d":"Британская «Комета» разваливалась в воздухе, мир остался без реактивных лайнеров, и два года летал один Ту-104","href":"/muzei/izobreteniya/den/06-17/"},"06-18":{"t":"Первая в мире геомагнитная обсерватория","d":"Компас врал, и никто не знал почему, пока Россия не выстроила сеть магнитных станций от Петербурга до Аляски","href":"/muzei/izobreteniya/den/06-18/"},"06-19":{"t":"Модель расширяющейся Вселенной, основа современной космологии","d":"Петербургский математик вывел, что Вселенная не может стоять на месте, и получил от Эйнштейна письмо с возражением","href":"/muzei/izobreteniya/den/06-19/"},"06-20":{"t":"Электрошлаковая сварка","d":"Металл толщиной в метр обычной сваркой не взять, и в Киеве стали варить его через слой расплавленного шлака","href":"/muzei/izobreteniya/den/06-20/"},"06-21":{"t":"«Вега»: ядро кометы Галлея вблизи · [У] 1986","d":"Комету Галлея ждали семьдесят шесть лет, и два советских аппарата первыми в мире сфотографировали её ядро вблизи","href":"/muzei/izobreteniya/den/06-21/"},"06-22":{"t":"Торпедная атака минных катеров · [У] С. О. Макаров, 1878","d":"Макаров возил катера на пароходе и спускал их ночью у турецкого берега — так торпеда впервые в истории потопила корабль","href":"/muzei/izobreteniya/den/06-22/"},"06-23":{"t":"Двигатели НК · [Р] Н. Д. Кузнецов, 1911","d":"НК-12 Кузнецова до сих пор самый мощный турбовинтовой двигатель мира, а его НК-33 купили американцы через сорок лет","href":"/muzei/izobreteniya/den/06-23/"},"06-24":{"t":"«Топаз»: реактор на орбите · [У] 1987","d":"Солнечные батареи в дальнем космосе бесполезны, и у нас сделали атомный реактор, работающий прямо на орбите","href":"/muzei/izobreteniya/den/06-24/"},"06-25":{"t":"Теория сверхпроводников второго рода (Нобель)","d":"Абрикосов объяснил, как магнитное поле пробивается в сверхпроводник вихрями, — из этой теории выросли сильные магниты","href":"/muzei/izobreteniya/den/06-25/"},"06-26":{"t":"Излучение Вавилова — Черенкова · [У] И. Е. Тамм, 1937","d":"Голубое свечение воды у реактора объяснили наши теоретики: частица летит быстрее света в воде, и вода светится","href":"/muzei/izobreteniya/den/06-26/"},"06-27":{"t":"«Зонд-5» — облёт Луны и возвращение · [У] 1968","d":"За три месяца до «Аполлона-8» Луну облетели две черепахи и вернулись на Землю живыми","href":"/muzei/izobreteniya/den/06-27/"},"06-28":{"t":"Первый в мире промышленный ядерный реактор «Аннушка» (первый в Евразии после Ф-1)","d":"Первый промышленный реактор Евразии запустили через три года после войны, и Курчатов сам стоял у пульта","href":"/muzei/izobreteniya/den/06-28/"},"06-29":{"t":"Алюминотермия · [У] Н. Н. Бекетов, 1859–1865","d":"Бекетов показал, что алюминий отбирает кислород у других металлов и горит при этом так, что плавит сталь","href":"/muzei/izobreteniya/den/06-29/"},"06-30":{"t":"Ракетно-космическая техника, крылатые ракеты","d":"Челомей придумал ракету, которая раскладывает крылья уже в полёте, выйдя из тесного контейнера подводной лодки","href":"/muzei/izobreteniya/den/06-30/"},"07-01":{"t":"Первая в мире теория происхождения жизни · [У] А. И. Опарин 1924","d":"Опарин первым сказал, что жизнь не вспыхнула чудом, а сварилась в океане, — американцы проверили это в колбе через 29 лет","href":"/muzei/izobreteniya/den/07-01/"},"07-02":{"t":"Первая в мире электрическая лампа (опыты)","d":"Лодыгин зажёг электрическую лампу за пять лет до Эдисона и первым в мире осветил ею городскую улицу","href":"/muzei/izobreteniya/den/07-02/"},"07-03":{"t":"Первый в мире метод искусственного осеменения животных · [У] И. И. Иванов 1899","d":"От одного жеребца — тысяча жеребят вместо десяти: так в русских конюшнях придумали то, на чём стоит мировое животноводство","href":"/muzei/izobreteniya/den/07-03/"},"07-04":{"t":"Закон гомологических рядов и первый в мире мировой банк семян · [У] Н. И. Вавилов 1920","d":"Сотрудники Вавилова умирали от голода в блокаду, но не тронули ни зерна из первого в мире банка семян","href":"/muzei/izobreteniya/den/07-04/"},"07-05":{"t":"Первый в мире институт переливания крови · [У] А. А. Богданов 1926","d":"Богданов основал первый в мире институт крови и погиб от собственного двенадцатого переливания","href":"/muzei/izobreteniya/den/07-05/"},"07-06":{"t":"Реакция Кучерова: из газа — сырьё для каучука и лекарств · [У] М. Г. Кучеров 1881","d":"Из газа, которым тогда светили улицы, Кучеров получил сырьё для каучука и лекарств — реакция его имени вошла в мировые учебники","href":"/muzei/izobreteniya/den/07-06/"},"07-07":{"t":"Первый в мире водолазный скафандр · [И] Гаузен, Кронштадт, 1829","d":"Гаузен опустил человека под воду в медном шлеме с воздушным шлангом — и водолаз впервые не нырял, а работал","href":"/muzei/izobreteniya/den/07-07/"},"07-08":{"t":"Первое в мире серийное судно на подводных крыльях «Ракета» · [У] Р. Е. Алексеев 1957","d":"Судно Алексеева на ходу вылезало из воды на крыльях и везло от Горького до Казани за семь часов вместо тридцати","href":"/muzei/izobreteniya/den/07-08/"},"07-09":{"t":"Сверхтекучесть жидкого гелия (Нобель)","d":"Капица нашёл жидкость без трения: охлаждённый гелий сам полз вверх по стенке и уходил из закрытого сосуда","href":"/muzei/izobreteniya/den/07-09/"},"07-10":{"t":"Самый большой в мире вертолёт В-12 (первый полёт)","d":"Вертолёт Миля поднял в небо сорок тонн — этот мировой рекорд не побит никем до сих пор","href":"/muzei/izobreteniya/den/07-10/"},"07-11":{"t":"Лазер и мазер (Нобель)","d":"Прохоров с Басовым заставили атомы светить одним лучом — за этот принцип лазера им дали Нобелевскую премию","href":"/muzei/izobreteniya/den/07-11/"},"07-12":{"t":"Первое в мире орудие на конвейере — ЗИС-3 · [У] В. Г. Грабин 1942","d":"Пушку Грабина собирали как автомобиль — она сходила с конвейера каждые двадцать минут, и немцы звали её гениальной","href":"/muzei/izobreteniya/den/07-12/"},"07-13":{"t":"Первая в мире государственная система здравоохранения (модель Семашко)","d":"Семашко сделал врача бесплатным для всей страны — такой государственной медицины мир до России не знал","href":"/muzei/izobreteniya/den/07-13/"},"07-14":{"t":"Первый в мире корабль быстрее 30 узлов — миноносец «Сокол» · [У] 1895","d":"Миноносец «Сокол» первым на планете перешагнул тридцать узлов — 30,3 на мерной миле, быстрее любого корабля мира","href":"/muzei/izobreteniya/den/07-14/"},"07-15":{"t":"Матричный принцип наследственности","d":"Кольцов за четверть века до открытия ДНК заявил, что наследственная молекула копирует себя по матрице, — и оказался прав","href":"/muzei/izobreteniya/den/07-15/"},"07-16":{"t":"Основатель мировой нейропсихологии","d":"Лурия по ошибкам речи раненого указывал, какой участок мозга разбит, — из этого выросла мировая нейропсихология","href":"/muzei/izobreteniya/den/07-16/"},"07-17":{"t":"«Союз» — «Аполлон»: первая в мире стыковка кораблей разных стран · [И] 17.07.1975","d":"Два корабля враждующих сверхдержав сцепились на орбите, и люки открылись — первое рукопожатие в космосе","href":"/muzei/izobreteniya/den/07-17/"},"07-18":{"t":"Основоположник трансплантологии органов","d":"Демихов пересаживал собакам сердце и лёгкие за двадцать лет до первой пересадки человеку — Барнард ездил учиться к нему","href":"/muzei/izobreteniya/den/07-18/"},"07-19":{"t":"Электрическая дуга и её применение","d":"Петров вырвал из батареи ослепительную дугу и первым сказал, что ею можно плавить металл и освещать улицы","href":"/muzei/izobreteniya/den/07-19/"},"07-20":{"t":"Первые в мире палеогеографические карты · [У] А. П. Карпинский 1880-е","d":"Карпинский нарисовал карты морей, которых никто не видел, — по его методу нефть ищут до сих пор","href":"/muzei/izobreteniya/den/07-20/"},"07-21":{"t":"Первый в мире полёт живых существ в стратосферу с возвратом (Дезик и Цыган)","d":"Дезик и Цыган ушли в стратосферу на ракете и вернулись живыми — до них с такой высоты не возвращался никто","href":"/muzei/izobreteniya/den/07-21/"},"07-22":{"t":"Самолёты «Су»","d":"Сухой строил машины, которые до сих пор держат небо: его Су-27 умеет остановиться в воздухе и встать на хвост","href":"/muzei/izobreteniya/den/07-22/"},"07-23":{"t":"Авиационные двигатели «ВК»","d":"Двигатели Климова подняли Як и МиГ-15 — его ВК-1 стал самым массовым реактивным мотором своего времени","href":"/muzei/izobreteniya/den/07-23/"},"07-24":{"t":"Реакция Чичибабина и первое отечественное производство лекарств · [У] А. Е. Чичибабин 1914","d":"Война отрезала Россию от немецких лекарств — Чичибабин за год наладил собственное производство","href":"/muzei/izobreteniya/den/07-24/"},"07-25":{"t":"Первая в мире женщина в открытом космосе · [И] С. Савицкая 25.07.1984","d":"Савицкая три с половиной часа резала и варила металл в открытом космосе — первой из женщин планеты","href":"/muzei/izobreteniya/den/07-25/"},"07-26":{"t":"Первая документально зафиксированная передача движущегося изображения (телефот) · [И] Б. П. Грабовский 1928","d":"Грабовский в Ташкенте передал по радио живого движущегося человека — первое электронное телевидение мира","href":"/muzei/izobreteniya/den/07-26/"},"07-27":{"t":"Объёмная (глубинная) голография","d":"Денисюк научил плёнку хранить предмет целиком — его голограмма оживает в обычном белом свете","href":"/muzei/izobreteniya/den/07-27/"},"07-28":{"t":"Первый в мире электрический омнибус городской линии · [У] И. В. Романов 1899","d":"За сто лет до нынешней моды по Петербургу возил пассажиров электрический омнибус Романова — денег на линию так и не нашли","href":"/muzei/izobreteniya/den/07-28/"},"07-29":{"t":"Протон-нейтронная модель атомного ядра","d":"Иваненко первым собрал ядро атома из протонов и нейтронов — на этой схеме стоит вся ядерная физика","href":"/muzei/izobreteniya/den/07-29/"},"07-30":{"t":"Электронное телевидение и иконоскоп","d":"Зворыкин, выученный в Петербурге у Розинга, отдал миру иконоскоп — и телевидение стало электронным","href":"/muzei/izobreteniya/den/07-30/"},"07-31":{"t":"Первый в мире высотный скафандр для лётчиков","d":"Чертовский сшил лётчику скафандр раньше всех в мире — человек смог дышать там, где воздуха уже нет","href":"/muzei/izobreteniya/den/07-31/"},"08-01":{"t":"Первый в мире арктический метеорологический прогноз (Визе)","d":"Визе первым связал тепло Гольфстрима и давление воздуха со льдами Арктики и научился предсказывать льды на месяцы вперёд.","href":"/muzei/izobreteniya/den/08-01/"},"08-02":{"t":"Первые в мире воздушно-десантные войска (учения РККА)","d":"2 августа 1930 года под Воронежем 12 бойцов Минова прыгнули с парашютами и подобрали оружие, сброшенное следом в мешках и ящиках.","href":"/muzei/izobreteniya/den/08-02/"},"08-03":{"t":"Первый в мире гусеничный (паровой) трактор","d":"Самоучка Блинов поставил на свой гусеничный трактор две паровые машины, по одной на гусеницу, и машина поворачивала за счёт разной скорости гусениц.","href":"/muzei/izobreteniya/den/08-03/"},"08-04":{"t":"Геология Сибири, открытие Байкальского разлома","d":"Обручев прошёл по Сибири и Центральной Азии тысячи вёрст и свёл всё увиденное в трёхтомную «Геологию Сибири».","href":"/muzei/izobreteniya/den/08-04/"},"08-05":{"t":"Истребители «МиГ»","d":"В 1977 году самолёт Микояна Е-266М поднялся на 37 650 метров, и этот мировой рекорд высоты для реактивного самолёта не побит до сих пор.","href":"/muzei/izobreteniya/den/08-05/"},"08-06":{"t":"Первый в мире суточный полёт человека в космос («Восток-2», Г. Титов)","d":"Герман Титов первым в мире проспал ночь на орбите, пока «Восток-2» за сутки 17 раз облетал Землю.","href":"/muzei/izobreteniya/den/08-06/"},"08-07":{"t":"Первая русская кругосветная экспедиция","d":"7 августа 1803 года «Надежда» и «Нева» ушли из Кронштадта, через три года они первыми под русским флагом обошли вокруг света.","href":"/muzei/izobreteniya/den/08-07/"},"08-08":{"t":"Микрохирургия глаза, первый в мире поток-метод операций","d":"Фёдоров поставил операции на глазах на конвейер «Ромашка»: стол вёз больного по кругу от хирурга к хирургу, и вместо трёх часов уходило полчаса.","href":"/muzei/izobreteniya/den/08-08/"},"08-09":{"t":"Первый в мире рамочный улей «Петербург»","d":"Пётр Прокопович первым в мире вставил в улей выдвижные рамки и брал соты с мёдом «без дыма и ножа», не губя пчелиную семью.","href":"/muzei/izobreteniya/den/08-09/"},"08-10":{"t":"Законы фотоэффекта, первый фотоэлемент","d":"Столетов собрал первый фотоэлемент из металлической сетки и пластины и доказал, что ток от света растёт ровно вместе с его яркостью.","href":"/muzei/izobreteniya/den/08-10/"},"08-11":{"t":"Первый в мире групповой космический полёт («Восток-3/4»)","d":"Николаев и Попович летели на двух «Востоках» в шести с половиной километрах друг от друга и первыми в мире говорили по радио с корабля на корабль.","href":"/muzei/izobreteniya/den/08-11/"},"08-12":{"t":"Самолёт схемы «летающее крыло»","d":"Черановский построил планёр из одного параболического крыла без хвоста, и в 1924 году его «Парабола» пролетела в Коктебеле дальше соперников.","href":"/muzei/izobreteniya/den/08-12/"},"08-13":{"t":"Рефлексы головного мозга, основы физиологии","d":"Сеченов положил кристаллик соли на мозг лягушки и увидел, что мозг умеет тормозить рефлексы — так в 1862 году открыли центральное торможение.","href":"/muzei/izobreteniya/den/08-13/"},"08-14":{"t":"Первая в мире успешная пересадка сердца от собаки к собаке","d":"В 1946 году Демихов пересадил собаке второе сердце прямо в грудь, и у неё рядом бились два сердца.","href":"/muzei/izobreteniya/den/08-14/"},"08-15":{"t":"Терменвокс — первый электромузыкальный инструмент","d":"Термен играл, не касаясь инструмента: рука в воздухе у антенны меняла звук, и в 1922 году в Кремле Ленин сам попробовал сыграть «Жаворонка».","href":"/muzei/izobreteniya/den/08-15/"},"08-16":{"t":"Теория корабля и качки, первый интегратор дифуравнений","d":"Крылов в 1904 году собрал машину, которая сама интегрировала дифференциальные уравнения качки корабля вместо ручного счёта.","href":"/muzei/izobreteniya/den/08-16/"},"08-17":{"t":"Первый надводный корабль, достигший Северного полюса (атомоход «Арктика»)","d":"Атомоход «Арктика» 17 августа 1977 года первым из надводных кораблей пробился сквозь льды к Северному полюсу.","href":"/muzei/izobreteniya/den/08-17/"},"08-18":{"t":"Первый в мире полностью закрытый водолазный аппарат (регенерация)","d":"Сентянин в 1909 году предложил водолазный аппарат, где выдох не уходил пузырями, а очищался и снова шёл в лёгкие.","href":"/muzei/izobreteniya/den/08-18/"},"08-19":{"t":"Белка и Стрелка: первое в мире возвращение живых существ с орбиты («Спутник-5»)","d":"Белка и Стрелка первыми вернулись с орбиты живыми, а щенка Стрелки Пушинку потом подарили Кеннеди в Белый дом.","href":"/muzei/izobreteniya/den/08-19/"},"08-20":{"t":"Стереокино без очков","d":"Иванов сделал фильтром сам экран, и в 1941 году москвичи смотрели объёмный «Концерт» в кинотеатре «Москва» без всяких очков.","href":"/muzei/izobreteniya/den/08-20/"},"08-21":{"t":"Первый в мире звуковой метод измерения давления","d":"Коротков описал на неполной странице звуковой метод, которым давление до сих пор меряют в каждой поликлинике мира.","href":"/muzei/izobreteniya/den/08-21/"},"08-22":{"t":"Первый в мире реактивный самолёт с крылом изменяемой стреловидности","d":"Сухой научил крыло поворачиваться прямо в полёте: опытный Су-7ИГ взлетел в 1966 году и стал прообразом Су-17.","href":"/muzei/izobreteniya/den/08-22/"},"08-23":{"t":"Жидкостный ракетный двигатель (ОР-1)","d":"Цандер переделал паяльную лампу в реактивный двигатель ОР-1 и в 1930 году запустил его на бензине и сжатом воздухе.","href":"/muzei/izobreteniya/den/08-23/"},"08-24":{"t":"Кибернетика, проект ОГАС (прообраз интернета), ЭВМ «МИР»","d":"Глушков ещё в начале 1960-х предложил связать вычислительные центры всей страны в одну сеть ОГАС, за годы до ARPANET.","href":"/muzei/izobreteniya/den/08-24/"},"08-25":{"t":"Синтез анилина, начало промышленной оргхимии","d":"Зинин в 1842 году превратил нитробензол в анилин, и из этой реакции выросла промышленность синтетических красителей.","href":"/muzei/izobreteniya/den/08-25/"},"08-26":{"t":"Первые в мире гиперболоидные сетчатые башни и конструкции","d":"Шухов в 1896 году поднял над Нижегородской выставкой первую в мире гиперболоидную башню из прямых стальных стержней.","href":"/muzei/izobreteniya/den/08-26/"},"08-27":{"t":"Киноаппарат (раньше Люмьеров)","d":"Тимченко придумал для киноаппарата прерывистый механизм «улитку» и снял им скачущего всадника за два года до Люмьеров.","href":"/muzei/izobreteniya/den/08-27/"},"08-28":{"t":"Первый в мире промышленный крекинг нефти — получение бензина из тяжёлой нефти (патент 1891)","d":"Шухов в 1891 году запатентовал крекинг: нефть под жаром и давлением распадалась на лёгкие фракции, из которых потом делали бензин.","href":"/muzei/izobreteniya/den/08-28/"},"08-29":{"t":"Первый русский паровоз и рельсовая дорога","d":"Черепановы в 1834 году пустили по чугунным рельсам Нижнего Тагила первый русский паровоз, тянувший до 200 пудов груза.","href":"/muzei/izobreteniya/den/08-29/"},"08-30":{"t":"Первая в мире адсорбция из растворов","d":"Ловиц первым в мире очистил углём мутный раствор и открыл адсорбцию — через 9 лет так спасали испорченную воду на флоте.","href":"/muzei/izobreteniya/den/08-30/"},"08-31":{"t":"Цветная фотография (метод трёх кадров)","d":"Прокудин-Горский снимал каждый кадр трижды через три цветных фильтра и привёз из поездок по империи тысячи цветных снимков.","href":"/muzei/izobreteniya/den/08-31/"},"09-01":{"t":"Хемосинтез (открытие)","d":"Виноградский нашёл бактерии, которые живут без солнечного света и берут энергию из серы и железа, а не из пищи.","href":"/muzei/izobreteniya/den/09-01/"},"09-02":{"t":"Электрический ракетный двигатель (ЭРД)","d":"Первый в мире электрический ракетный двигатель Глушко собрал в 1929-м — сегодня такие моторы водят спутники по орбите.","href":"/muzei/izobreteniya/den/09-02/"},"09-03":{"t":"Математическая теория оптимального управления","d":"Понтрягин ослеп в четырнадцать лет — и вывел принцип максимума, по которому сегодня считают траектории ракет.","href":"/muzei/izobreteniya/den/09-03/"},"09-04":{"t":"Местная анестезия и мазь Вишневского","d":"Вишневский научился оперировать без общего наркоза: тугая струя новокаина шаг за шагом раздвигала ткани перед скальпелем.","href":"/muzei/izobreteniya/den/09-04/"},"09-05":{"t":"Научная клиническая медицина, первая бесплатная больничная лаборатория","d":"Боткин назвал желтуху заразной болезнью за полвека до открытия вируса — потому её и зовут болезнью Боткина.","href":"/muzei/izobreteniya/den/09-05/"},"09-06":{"t":"Первый в мире метод непрерывной разливки стали","d":"Сталь льют не в формы, а бесконечной лентой — одна из первых промышленных таких машин заработала в Горьком в 1955-м.","href":"/muzei/izobreteniya/den/09-06/"},"09-07":{"t":"Первый в мире телеграф в Зимнем дворце (между дворцами Петербурга)","d":"Шиллинг протянул провода между залами, и стрелки на другом конце повторяли каждое слово без гонца и конной почты.","href":"/muzei/izobreteniya/den/09-07/"},"09-08":{"t":"Водородный двигатель (практическое применение, блокадный Ленинград)","d":"В блокадном Ленинграде бензина не было, и лейтенант Шелищ завёл моторы аэростатных лебёдок на водороде из старых аэростатов.","href":"/muzei/izobreteniya/den/09-08/"},"09-09":{"t":"Химия элементоорганических соединений","d":"Несмеянов создал химию элементоорганики и всерьёз делал искусственную чёрную икру из молочного белка.","href":"/muzei/izobreteniya/den/09-09/"},"09-10":{"t":"Дефибриллятор (электрический запуск сердца)","d":"Гурвич понял, что сердце губит не удар током, а хаос, и придумал гасить хаос одним коротким разрядом конденсатора.","href":"/muzei/izobreteniya/den/09-10/"},"09-11":{"t":"Истребители «Ла»","d":"Ла-5 переделали из неудачного ЛаГГ за считанные месяцы, и на нём Кожедуб начал счёт своих воздушных побед.","href":"/muzei/izobreteniya/den/09-11/"},"09-12":{"t":"«Луна-2», первый в мире аппарат, достигший другого небесного тела","d":"«Луна-2» первой из земных вещей коснулась другого небесного тела и доставила на Луну советские вымпелы.","href":"/muzei/izobreteniya/den/09-12/"},"09-13":{"t":"Гидроинтегратор — первая в мире аналоговая ЭВМ","d":"Лукьянов считал прочность бетона водой: уровни в стеклянных трубках решали уравнения, которые на бумаге не поддавались.","href":"/muzei/izobreteniya/den/09-13/"},"09-14":{"t":"Первые в мире дуговые электрические лампы («свеча Яблочкова»)","d":"Свечи Яблочкова в 1878-м осветили парижские улицы, и европейцы называли этот свет «русским светом».","href":"/muzei/izobreteniya/den/09-14/"},"09-15":{"t":"Теория химического строения веществ","d":"Бутлеров первым сказал, что у молекулы есть строение, — и по этой подсказке получил вещество, которого ещё не знали.","href":"/muzei/izobreteniya/den/09-15/"},"09-16":{"t":"Первый в мире самолёт-биплан с закрытой кабиной экипажа","d":"У «Ильи Муромца» был отапливаемый салон с креслами и даже уборная — в 1914 году, когда другие лётчики сидели на ветру.","href":"/muzei/izobreteniya/den/09-16/"},"09-17":{"t":"Теория космонавтики и ракетодинамики","d":"Глухой учитель из Калуги вывел формулу, по которой до сих пор считают каждую ракету, что уходит в космос.","href":"/muzei/izobreteniya/den/09-17/"},"09-18":{"t":"Космогония, теория происхождения планет; освоение Севморпути","d":"«Сибиряков» Шмидта первым прошёл Севморпуть за одну навигацию и дошёл последний отрезок под самодельными парусами.","href":"/muzei/izobreteniya/den/09-18/"},"09-19":{"t":"Первый в мире автомат: автоматическая винтовка Фёдорова, отвергнутая императором","d":"Автомат Фёдорова пошёл в бой в 1916-м: впервые целую роту вооружили ручным оружием, стреляющим очередями.","href":"/muzei/izobreteniya/den/09-19/"},"09-20":{"t":"Аэрофотоаппарат (аэрофотосъёмка)","d":"Петербург впервые сфотографировали с воздушного шара в 1886-м — снимал Кованько, аппарат готовил Срезневский.","href":"/muzei/izobreteniya/den/09-20/"},"09-21":{"t":"Электродвигатель, гальванопластика, телеграф","d":"В 1838 году по Неве против течения прошла лодка с электромотором Якоби и четырнадцатью пассажирами на борту.","href":"/muzei/izobreteniya/den/09-21/"},"09-22":{"t":"Первый в мире оперативный метеопрогноз на несколько суток","d":"Визе вычислил неоткрытый остров по дрейфу чужой шхуны — и через шесть лет на этом месте действительно нашли землю.","href":"/muzei/izobreteniya/den/09-22/"},"09-23":{"t":"Первая в мире ЭВМ для экономических расчётов «БЭСМ-6»","d":"БЭСМ-6 делала миллион операций в секунду, и на ней считали полёт «Союза» и «Аполлона» в 1975 году.","href":"/muzei/izobreteniya/den/09-23/"},"09-24":{"t":"Математика, дивергенция и уравнения физики","d":"Формулу, которую мир зовёт теоремой Гаусса, Остроградский доказал в общем виде и первым представил академии.","href":"/muzei/izobreteniya/den/09-24/"},"09-25":{"t":"Первое в мире систематическое картографирование Арктики","d":"Отряды Великой Северной экспедиции за десять лет сплошь засняли берег Ледовитого океана от Печоры до Колымы, где карта была пустой.","href":"/muzei/izobreteniya/den/09-25/"},"09-26":{"t":"Учение об условных рефлексах (Нобель)","d":"Павлов хотел понять желудок, а открыл мозг: собака пускала слюну на шаги лаборанта, ещё не видя еды.","href":"/muzei/izobreteniya/den/09-26/"},"09-27":{"t":"Первая в мире подводная электрическая мина (Якоби)","d":"Мины Якоби у Кронштадта в Крымскую войну замыкали цепь от удара днища, и союзный флот к крепости не подошёл.","href":"/muzei/izobreteniya/den/09-27/"},"09-28":{"t":"Первый в Европе и Азии ядерный реактор Ф-1 (атомная промышленность)","d":"Реактор Ф-1 запустили в 1946-м в Москве, и он проработал больше семидесяти лет — дольше любого другого в мире.","href":"/muzei/izobreteniya/den/09-28/"},"09-29":{"t":"Первая в мире теория воздушно-реактивного двигателя · [У] Б. С. Стечкин 1929 · ✅","d":"Стечкин рассчитал реактивный двигатель за год до первого патента на него — по его формулам летает вся авиация","href":"/muzei/izobreteniya/den/09-29/"},"09-30":{"t":"Стратостат «СССР-1», мировой рекорд высоты","d":"Стратостат «СССР-1» поднял троих на девятнадцать километров — выше человека до этого не поднимался никто.","href":"/muzei/izobreteniya/den/09-30/"},"10-01":{"t":"Первый в мире беспилотный вертолёт (советские испытания)","d":"Вертолёт Ка-37 фирмы Камова в 1993 году взлетел без лётчика и пошёл по заданной траектории на двух соосных винтах.","href":"/muzei/izobreteniya/den/10-01/"},"10-02":{"t":"Первый в мире газотурбинный локомотив","d":"Газотурбовоз Г1 1959 года тянул составы авиационной по сути турбиной — локомотив без пара, котла и топки.","href":"/muzei/izobreteniya/den/10-02/"},"10-03":{"t":"Теория сверхпроводимости и сверхтекучести (Нобель)","d":"Гинзбург получил Нобелевскую премию в 87 лет за уравнения, которые написал с Ландау ещё в 1950 году.","href":"/muzei/izobreteniya/den/10-03/"},"10-04":{"t":"«Спутник-1», первый в мире искусственный спутник Земли","d":"Спутник весил 83 килограмма и умел только пищать, но этот писк из космоса слушал по радио весь мир.","href":"/muzei/izobreteniya/den/10-04/"},"10-05":{"t":"Первый в мире Центральный телеграф и Киевский вокзал (ж/б конструкции)","d":"Шухов перекрыл перроны Киевского вокзала аркой пролётом 47,9 метра, а Рерберг поставил под ней вокзал, позже — и Центральный телеграф.","href":"/muzei/izobreteniya/den/10-05/"},"10-06":{"t":"Геология и геохимия Сибири, «Земля Санникова»","d":"Геолог Обручев написал роман «Земля Санникова» о тёплой земле среди льдов, которую искали, но так и не нашли.","href":"/muzei/izobreteniya/den/10-06/"},"10-07":{"t":"Первые в мире снимки обратной стороны Луны («Луна-3»)","d":"В 1959-м «Луна-3» сфотографировала обратную сторону Луны, проявила плёнку прямо на борту и передала снимки по радио.","href":"/muzei/izobreteniya/den/10-07/"},"10-08":{"t":"Первый в мире управляемый реактивный снаряд С-75 (сбил U-2)","d":"Первым самолётом, сбитым зенитной ракетой, стал разведчик над Пекином в 1959-м — его достала советская С-75.","href":"/muzei/izobreteniya/den/10-08/"},"10-09":{"t":"Метод хранения и переливания крови (в т.ч. трупной)","d":"В 1930 году Юдин первым в мире перелил человеку кровь умершего донора — и больной выжил.","href":"/muzei/izobreteniya/den/10-09/"},"10-10":{"t":"Геология Сибири и Азии","d":"Геолог Обручев в 1939 году возглавил Институт мерзлотоведения Академии наук, и институт получил его имя ещё при жизни учёного.","href":"/muzei/izobreteniya/den/10-10/"},"10-11":{"t":"Первый в мире сеанс радиосвязи через Луну как отражатель","d":"Радиофизики Горьковского университета в 1954–1957 годах посылали сигнал к Луне и ловили его отражение, проложив путь советской связи через Луну.","href":"/muzei/izobreteniya/den/10-11/"},"10-12":{"t":"«Восход-1», первый в мире многоместный космический корабль","d":"Трое полетели на «Восходе-1» без скафандров — иначе они не помещались в корабль, рассчитанный на одного.","href":"/muzei/izobreteniya/den/10-12/"},"10-13":{"t":"Первый в мире реактивный бомбардировщик Ту-16","d":"Бомбардировщик Ту-16 поднялся в небо в 1952-м, а его китайская копия H-6 выпускается до сих пор.","href":"/muzei/izobreteniya/den/10-13/"},"10-14":{"t":"Первое в мире хождение с живым сердцем донора (Демихов)","d":"Собака Демихова бегала по двору с двумя сердцами — своим и пересаженным, и хирурги со всего мира ехали к нему учиться.","href":"/muzei/izobreteniya/den/10-14/"},"10-15":{"t":"Электронный парамагнитный резонанс (ЭПР)","d":"Электронный парамагнитный резонанс Завойский открыл в Казани в 1944-м, когда шла война и не хватало даже приборов.","href":"/muzei/izobreteniya/den/10-15/"},"10-16":{"t":"Первая в мире сварка в открытом космосе","d":"В 1969-м Кубасов первым в мире сварил металл в космосе — аппарат «Вулкан» стоял в отсеке, откуда стравили воздух.","href":"/muzei/izobreteniya/den/10-16/"},"10-17":{"t":"Первый в мире орбитальный полёт длительностью более суток (Титов, «Восток-2»)","d":"Герман Титов первым в мире проспал в космосе — и проснулся оттого, что руки висели в невесомости сами по себе.","href":"/muzei/izobreteniya/den/10-17/"},"10-18":{"t":"Лампа накаливания (нить, спираль)","d":"Лодыгин осветил петербургскую улицу лампами накаливания в 1873-м — за шесть лет до знаменитой лампы Эдисона.","href":"/muzei/izobreteniya/den/10-18/"},"10-19":{"t":"Металловедение, точки Чернова (первое в мире учение о структуре стали)","d":"Чернов открыл, что сталь при нагреве проходит критические точки, и объяснил, почему лопались стволы пушек.","href":"/muzei/izobreteniya/den/10-19/"},"10-20":{"t":"Пенный огнетушитель","d":"Учитель Лоран залил горящую нефть пеной из своего огнетушителя, и пожар, который вода только разносила, погас.","href":"/muzei/izobreteniya/den/10-20/"},"10-21":{"t":"Электромагнитный телеграф, первый в истории","d":"В 1832-м в петербургской квартире Шиллинга стрелки дрогнули от тока из другой комнаты — так прошла первая телеграмма.","href":"/muzei/izobreteniya/den/10-21/"},"10-22":{"t":"«Венера-9»: первые в мире снимки поверхности другой планеты","d":"«Венера-9» передала первые снимки с поверхности другой планеты и проработала 53 минуты в аду из жара и давления.","href":"/muzei/izobreteniya/den/10-22/"},"10-23":{"t":"Теория излучения Вавилова-Черенкова (Нобель)","d":"Черенков увидел свечение, а Франк и Тамм объяснили его: частица обгоняет свет в воде, как самолёт свой звук.","href":"/muzei/izobreteniya/den/10-23/"},"10-24":{"t":"Первый советский пенициллин, антибиотики","d":"Ермольева получила советский пенициллин в 1942-м, и приехавший в Москву Флори сравнивал его со своим.","href":"/muzei/izobreteniya/den/10-24/"},"10-25":{"t":"Баллистические ракеты подводных лодок","d":"Первая в мире баллистическая ракета стартовала с подводной лодки в 1955-м, и эту школу дальше вёл Макеев.","href":"/muzei/izobreteniya/den/10-25/"},"10-26":{"t":"Первый в мире искусственный рубин (промышленное производство)","d":"Институт кристаллографии в 1939 году вырастил первый советский синтетический рубин, и вскоре он стал камнем-опорой в часах и приборах.","href":"/muzei/izobreteniya/den/10-26/"},"10-27":{"t":"Научная селекция растений, новые сорта","d":"Мичурин вывел сотни сортов и заставил южные яблони и груши плодоносить под Тамбовом.","href":"/muzei/izobreteniya/den/10-27/"},"10-28":{"t":"Открытие вирусов (основы вирусологии)","d":"Ивановский пропустил сок больного табака через фильтр, задерживавший все микробы, а болезнь всё равно передалась.","href":"/muzei/izobreteniya/den/10-28/"},"10-29":{"t":"Физика полупроводников (научная школа)","d":"Иоффе собрал в Ленинграде физтех, откуда вышли Капица, Курчатов и Семёнов, — его звали «папой Иоффе».","href":"/muzei/izobreteniya/den/10-29/"},"10-30":{"t":"Первая в мире автоматическая стыковка на орбите («Космос-186/188»)","d":"Два беспилотных корабля нашли друг друга на орбите и состыковались сами — люди только следили за этим с Земли.","href":"/muzei/izobreteniya/den/10-30/"},"10-31":{"t":"Проект реактивного летательного аппарата","d":"Кибальчич нарисовал ракетный летательный аппарат в камере смертника, за несколько дней до казни в 1881 году.","href":"/muzei/izobreteniya/den/10-31/"},"11-01":{"t":"Первое в мире массовое применение живой вакцины от полиомиелита","d":"Чумаков и Смородинцев за год привили живой вакциной миллионы детей — вакцина Сэбина впервые массово сработала у нас.","href":"/muzei/izobreteniya/den/11-01/"},"11-02":{"t":"Первая ЭВМ в континентальной Европе (МЭСМ)","d":"МЭСМ, первую ЭВМ континентальной Европы, Лебедев собрал в бывшем монастыре под Киевом в 1950 году.","href":"/muzei/izobreteniya/den/11-02/"},"11-03":{"t":"Первый в мире электромагнитный сейсмограф","d":"Сейсмограф Голицына писал землетрясения током, а не пером, и по его схеме сейсмостанции мира работали полвека.","href":"/muzei/izobreteniya/den/11-03/"},"11-04":{"t":"Первый в мире многомоторный тяжёлый самолёт «Илья Муромец»","d":"В 1914-м «Илья Муромец» поднял шестнадцать человек и собаку — рекорд грузоподъёмности тех лет.","href":"/muzei/izobreteniya/den/11-04/"},"11-05":{"t":"Первая в мире массовая операция под эфирным наркозом в военных условиях","d":"Под аулом Салта в 1847-м Пирогов оперировал раненых под эфиром на глазах у других солдат, чтобы те не боялись.","href":"/muzei/izobreteniya/den/11-05/"},"11-06":{"t":"Агрохимия и научное применение удобрений","d":"Прянишников объяснил, чем кормить поле, чтобы оно не истощалось, и его «Агрохимию» переиздавали десятки раз.","href":"/muzei/izobreteniya/den/11-06/"},"11-07":{"t":"Стратегические ракеты (Р-12, Р-36)","d":"Ракеты Янгеля на долгохранимом топливе стояли заправленными годами и взлетали за минуты, а не за часы.","href":"/muzei/izobreteniya/den/11-07/"},"11-08":{"t":"Геохимия и минералогия","d":"Ферсман нашёл в Хибинах апатит, и на пустом месте за полярным кругом вырос город Кировск.","href":"/muzei/izobreteniya/den/11-08/"},"11-09":{"t":"Автомат перекоса — «сердце» вертолёта","d":"Студент Юрьев в 1911-м придумал автомат перекоса — без этой детали не летает ни один вертолёт планеты.","href":"/muzei/izobreteniya/den/11-09/"},"11-10":{"t":"БТА: крупнейший телескоп мира 1975–1993 и первая азимутальная монтировка большого зеркала · [У] 1975 · ✅","d":"Восемнадцать лет самый большой глаз планеты смотрел в небо с Кавказа, и его поворотная схема стала мировым стандартом","href":"/muzei/izobreteniya/den/11-10/"},"11-11":{"t":"Первая серийная подводная лодка","d":"Подлодку Джевецкого крутил ногами сам экипаж, а в 1881-м их построили полсотни — первая серия подлодок в мире.","href":"/muzei/izobreteniya/den/11-11/"},"11-12":{"t":"Первый в мире атомный ледокол «Ленин» (ввод в эксплуатацию)","d":"«Ленин» стал первым в мире надводным судном с атомным реактором и мог ходить во льдах месяцами без захода в порт.","href":"/muzei/izobreteniya/den/11-12/"},"11-13":{"t":"Закон гомологических рядов, первый в мире банк семян","d":"В блокаду сотрудники Вавилова умирали от голода рядом с мешками семян, но не съели ни зерна из коллекции.","href":"/muzei/izobreteniya/den/11-13/"},"11-14":{"t":"Первый в мире миномёт","d":"В Порт-Артуре капитан Гобято стрелял навесом прямо в японские окопы — так появился миномёт.","href":"/muzei/izobreteniya/den/11-14/"},"11-15":{"t":"«Буран», первая в мире автоматическая посадка орбитального корабля","d":"Корабль вернулся из космоса и сел на полосу сам — на борту не было ни одного человека.","href":"/muzei/izobreteniya/den/11-15/"},"11-16":{"t":"Первый в мире серийный зенитный ракетный комплекс С-25","d":"Вокруг Москвы в 1950-х выросли два кольца ракетных позиций С-25, и их бетонные дороги до сих пор видны на карте.","href":"/muzei/izobreteniya/den/11-16/"},"11-17":{"t":"«Луноход-1», первый в мире планетоход","d":"«Луноходом-1» управляли с Земли пятеро, и каждая команда доходила до Луны с задержкой в несколько секунд.","href":"/muzei/izobreteniya/den/11-17/"},"11-18":{"t":"Первая в России прокладка кабелей под водой и телефонизация","d":"Шиллинг в 1812 году взорвал мину на Неве током по проводу, обмотанному каучуком и проложенному по дну, — первым подводным кабелем.","href":"/muzei/izobreteniya/den/11-18/"},"11-19":{"t":"Основоположник русской науки; мозаика, наука о стекле, закон сохранения","d":"Ломоносов сам варил цветное стекло для мозаик и набрал из него «Полтавскую баталию» размером со стену.","href":"/muzei/izobreteniya/den/11-19/"},"11-20":{"t":"Эволюционная сравнительная эмбриология — основа дарвинизма","d":"Ковалевский увидел у асцидии зародыш со спинной струной и доказал Дарвину, что мы в родстве с морскими мешочками.","href":"/muzei/izobreteniya/den/11-20/"},"11-21":{"t":"Катализ под высоким давлением","d":"Ипатьев заставил реакции идти в стальной «бомбе» под огромным давлением, и так появился высокооктановый бензин.","href":"/muzei/izobreteniya/den/11-21/"},"11-22":{"t":"Вертолёты «Ми»","d":"Ми-12 Миля поднял в 1969-м больше сорока тонн, и этот рекорд для вертолётов не побит до сих пор.","href":"/muzei/izobreteniya/den/11-22/"},"11-23":{"t":"Первый в мире сверхтекучий гелий (открытие свойства)","d":"Охлаждённый гелий у Капицы потёк сквозь щель, куда не проходил даже газ, — жидкость потеряла вязкость.","href":"/muzei/izobreteniya/den/11-23/"},"11-24":{"t":"Первый в мире реактивный истребитель МиГ-19 со сверхзвуковой скоростью","d":"МиГ-19 стал первым советским серийным истребителем, который переходил звуковой барьер в горизонтальном полёте.","href":"/muzei/izobreteniya/den/11-24/"},"11-25":{"t":"Военно-полевая хирургия и наркоз в полевых условиях","d":"Пирогов первым в мире оперировал под наркозом прямо на поле боя — и сделал так десять тысяч операций.","href":"/muzei/izobreteniya/den/11-25/"},"11-26":{"t":"Первый в мире двуствольный пулемёт (шкас)","d":"ШКАС стрелял тридцать раз в секунду — в 1930-е ни один авиапулемёт мира не стрелял так часто.","href":"/muzei/izobreteniya/den/11-26/"},"11-27":{"t":"Трёхфазная система переменного тока","d":"Розетки, моторы и линии электропередачи сегодня трёхфазные — эту систему в 1889 году придумал русский инженер.","href":"/muzei/izobreteniya/den/11-27/"},"11-28":{"t":"Первый в мире ядерный взрыв под землёй (мирный)","d":"Взрывом «Чаган» в 1965-м выкопали озеро в казахской степи, и вода в нём радиоактивна до сих пор.","href":"/muzei/izobreteniya/den/11-28/"},"11-29":{"t":"Первая в мире трёхфазная электростанция (Лауфен–Франкфурт, роль Доливо-Добровольского)","d":"В 1891-м ток пробежал 175 километров от Лауффена до Франкфурта, и на выставке загорелась тысяча ламп.","href":"/muzei/izobreteniya/den/11-29/"},"11-30":{"t":"Первый в мире реактивный пассажирский лайнер Ту-144 (первый полёт состава)","d":"Сверхзвуковой Ту-144 перед посадкой выпускал за кабиной маленькие крылья, чтобы садиться на обычной скорости.","href":"/muzei/izobreteniya/den/11-30/"},"12-01":{"t":"Неевклидова геометрия","d":"Две тысячи лет постулат о параллельных не смел тронуть никто — профессор из Казани усомнился и оказался прав.","href":"/muzei/izobreteniya/den/12-01/"},"12-02":{"t":"Первая в мире посадка на Марс («Марс-3»)","d":"«Марс-3» первым мягко сел на Марс, передал сигнал лишь считаные секунды, и связь навсегда оборвалась.","href":"/muzei/izobreteniya/den/12-02/"},"12-03":{"t":"Токарный станок с суппортом","d":"Токарный станок с механическим суппортом Нартов построил для Петра почти на восемьдесят лет раньше англичанина Модсли.","href":"/muzei/izobreteniya/den/12-03/"},"12-04":{"t":"Артиллерийский оптический прицел","d":"Нартов в 1745 году сделал для артиллерии прицел со зрительной трубой и уровнем, чтобы быстро наводить орудие на цель с батареи.","href":"/muzei/izobreteniya/den/12-04/"},"12-05":{"t":"«Ленин», первый в мире атомный надводный корабль (ледокол)","d":"Атомный ледокол «Ленин» спустили на воду в 1957-м, через два месяца после первого спутника.","href":"/muzei/izobreteniya/den/12-05/"},"12-06":{"t":"Физико-химический анализ","d":"Курнаков научился читать сплавы по графикам: излом кривой плавления сразу показывал, какое вещество спряталось внутри.","href":"/muzei/izobreteniya/den/12-06/"},"12-07":{"t":"Внеосевой (зеркальный) телескоп","d":"Ломоносов наклонил зеркало телескопа, чтобы голова наблюдателя не загораживала свет, — Гершель так же сделал позже.","href":"/muzei/izobreteniya/den/12-07/"},"12-08":{"t":"БЭСМ — одна из самых быстрых ЭВМ в мире (1953)","d":"БЭСМ в 1953-м считала восемь тысяч операций в секунду — быстрее любой машины Европы того времени.","href":"/muzei/izobreteniya/den/12-08/"},"12-09":{"t":"Соосный несущий винт (прототип вертолёта)","d":"В 1754 году Ломоносов показал Академии модель с двумя винтами, крутившимися навстречу, — прадеда соосных вертолётов.","href":"/muzei/izobreteniya/den/12-09/"},"12-10":{"t":"Кардиохирургия, аппарат искусственного сердца, биокибернетика","d":"Амосов сделал за жизнь больше шести тысяч операций на сердце и сам собрал свой аппарат искусственного кровообращения.","href":"/muzei/izobreteniya/den/12-10/"},"12-11":{"t":"Первый в мире телеуправляемый торпедный катер","d":"Пильчиков в 1898 году в одесском зале радиоволнами сквозь стены зажёг маяк, выстрелил из пушки и подорвал модель яхты.","href":"/muzei/izobreteniya/den/12-11/"},"12-12":{"t":"Правило Марковникова, взаимное влияние атомов в молекуле","d":"Правило Марковникова учат химики всего мира, хотя напечатал он его на русском, в диссертации, которую на Западе почти не читали.","href":"/muzei/izobreteniya/den/12-12/"},"12-13":{"t":"Первый в мире серийный МиГ-15 — реактивный истребитель нового поколения","d":"В Корее МиГ-15 оказался таким сюрпризом, что американцы обещали сто тысяч долларов за угнанный экземпляр.","href":"/muzei/izobreteniya/den/12-13/"},"12-14":{"t":"Мазер и лазер (принцип квантовых генераторов, Нобель)","d":"Басов и Прохоров заставили атомы светить строго в такт — их лазер сегодня режет сталь и возвращает людям зрение.","href":"/muzei/izobreteniya/den/12-14/"},"12-15":{"t":"Первая в мире посадка на другую планету, Венеру («Венера-7»)","d":"«Венера-7» передала с поверхности чужой планеты двадцать минут слабого сигнала, который нашли в записях лишь потом.","href":"/muzei/izobreteniya/den/12-15/"},"12-16":{"t":"Первая внутриконтинентальная станция в Антарктиде «Восток» (полюс холода)","d":"На станции «Восток» в 1983-м намерили минус 89,2 — самую низкую температуру, когда-либо измеренную на Земле.","href":"/muzei/izobreteniya/den/12-16/"},"12-17":{"t":"Первая в мире централизованная система теплоснабжения","d":"В 1924 году в Ленинграде к электростанции подключили жилой дом на Фонтанке, и с этого началась советская теплофикация.","href":"/muzei/izobreteniya/den/12-17/"},"12-18":{"t":"Экраноплан и суда на подводных крыльях","d":"«Каспийского монстра» Алексеева разведчики приняли за невиданный самолёт, летающий в нескольких метрах над морем.","href":"/muzei/izobreteniya/den/12-18/"},"12-19":{"t":"Первый советский персональный ЭВМ «МИР» для инженеров","d":"ЭВМ «МИР» понимала формулы, как их пишет инженер, — без программиста между человеком и машиной.","href":"/muzei/izobreteniya/den/12-19/"},"12-20":{"t":"Первая в мире дрейфующая полярная станция «СП-1»","d":"Четверо папанинцев 274 дня жили на дрейфующей льдине, пока она не раскололась прямо у их палатки.","href":"/muzei/izobreteniya/den/12-20/"},"12-21":{"t":"Кристаллография: вывод всех 230 пространственных групп (первое в мире)","d":"Фёдоров вывел все 230 способов, которыми атомы могут повторяться в кристалле, и это число с тех пор не изменилось.","href":"/muzei/izobreteniya/den/12-21/"},"12-22":{"t":"Инерционный аккумулятор и первая ветроэлектростанция","d":"Курский самоучка Уфимцев запасал энергию ветра в тяжёлом маховике, чтобы свет не гас, когда ветер стихал.","href":"/muzei/izobreteniya/den/12-22/"},"12-23":{"t":"Первый в мире врач, предложивший противочумные прививки","d":"Самойлович в чумную Москву 1771 года предложил прививать от чумы и проверял свою дезинфекцию на себе.","href":"/muzei/izobreteniya/den/12-23/"},"12-24":{"t":"Первый в мире алмаз в Якутии (промышленное месторождение «Мир»)","d":"Геологи нашли в Якутии алмазную трубку и отправили в Москву шифровку: «Закурили трубку мира, табак отличный».","href":"/muzei/izobreteniya/den/12-24/"},"12-25":{"t":"Первый в мире ядерный реактор на европейском континенте Ф-1","d":"В Рождество 1946 года в Москве запустили реактор Ф-1 — первую цепную реакцию в Европе и Азии.","href":"/muzei/izobreteniya/den/12-25/"},"12-26":{"t":"Первый в мире сверхзвуковой стратегический бомбардировщик Ту-160","d":"Ту-160 — самый тяжёлый боевой самолёт с изменяемой стреловидностью крыла, лётчики прозвали его «Белым лебедем».","href":"/muzei/izobreteniya/den/12-26/"},"12-27":{"t":"Первый в мире чертёж механизма гусеницы (Блинов)","d":"Блинов в 1879-м получил привилегию на «вагон с бесконечными рельсами» — так выглядела гусеница до слова «гусеница».","href":"/muzei/izobreteniya/den/12-27/"},"12-28":{"t":"Учение о природной очаговости чумы (мировой приоритет)","d":"Заболотный выяснил, что чуму в степи хранят сурки и суслики, и для проверки привил себе противочумную вакцину.","href":"/muzei/izobreteniya/den/12-28/"},"12-29":{"t":"Первый в мире массовый серийный трактор «Фордзон-Путиловец» (СССР начал выпуск раньше США)","d":"В 1924-м Путиловский завод выпустил трактор по американскому образцу, и он стал первым массовым трактором страны.","href":"/muzei/izobreteniya/den/12-29/"},"12-30":{"t":"Первая в мире гиперзвуковая крылатая ракета (прототип «Метеорит»)","d":"Крылатая ракета «Метеорит» Челомея летела на высоте свыше 20 километров втрое быстрее звука на дальность больше 5000 километров.","href":"/muzei/izobreteniya/den/12-30/"},"12-31":{"t":"Первый в мире полёт сверхзвукового пассажирского самолёта (Ту-144)","d":"Ту-144 поднялся в небо в последний день 1968 года — на два месяца раньше «Конкорда».","href":"/muzei/izobreteniya/den/12-31/"}};
